407	export const KEY_TASKS: { category: string; name: string }[] = [
408	  { category: "Fire Marshal", name: "Submit To FM/EC" },
409	  { category: "ID Sign", name: "Submit ID Sign Order" },
410	  { category: "Show Bucket", name: "Bucket Due Date" },
411	];
412	
413	export function isKeyTask(task: any) {
414	  return KEY_TASKS.some((k) => k.category === task.category && k.name === task.name);
415	}
416	
417	const editTaskSchema = z.object({
418	  name: z.string().min(1, "Name is required"),
419	  category: z.string().optional(),
420	  dueDate: z.string().optional(),
421	  dueDateRule: z.string().optional(),
422	  notes: z.string().optional(),
423	});
424	
425	function TaskRow({ task, showId, onToggle, onDelete }: { task: any, showId: number, onToggle: () => void, onDelete: () => void }) {
426	  const [expanded, setExpanded] = useState(false);
427	  const [editOpen, setEditOpen] = useState(false);
428	  const [datePickerOpen, setDatePickerOpen] = useState(false);
429	  const [justCompleted, setJustCompleted] = useState(false);
430	
431	  const handleToggle = () => {
432	    if (!task.completed) {
433	      setJustCompleted(true);
434	      setTimeout(() => setJustCompleted(false), 650);
435	    }
436	    onToggle();
437	  };
438	  const urgency = getUrgencyInfo(task.dueDate);
439	  const queryClient = useQueryClient();
440	  const { toast } = useToast();
441	  const updateTask = useUpdateTask();
442	
443	  const onUpdateCompletedAt = (dateStr: string) => {
444	    if (!dateStr) return;
445	    updateTask.mutate(
446	      { showId, taskId: task.id, data: { completedAt: new Date(dateStr).toISOString() } as any },
447	      {
448	        onSuccess: () => {
449	          toast({ title: "Completion date updated" });
450	          setDatePickerOpen(false);
451	          queryClient.invalidateQueries({ queryKey: getListTasksQueryKey(showId) });
452	        },
453	        onError: () => toast({ title: "Error updating date", variant: "destructive" }),
454	      }
455	    );
456	  };
457	
458	  const form = useForm<z.infer<typeof editTaskSchema>>({
459	    resolver: zodResolver(editTaskSchema),
460	    defaultValues: {
461	      name: task.name,
462	      category: task.category ?? "",
463	      dueDate: task.dueDate ? String(task.dueDate).split("T")[0] : "",
464	      dueDateRule: task.dueDateRule ?? "",
465	      notes: task.notes ?? "",
466	    },
467	  });
468	
469	  const openEdit = () => {
470	    form.reset({
471	      name: task.name,
472	      category: task.category ?? "",
473	      dueDate: task.dueDate ? String(task.dueDate).split("T")[0] : "",
474	      dueDateRule: task.dueDateRule ?? "",
475	      notes: task.notes ?? "",
476	    });
477	    setEditOpen(true);
478	  };
479	
480	  const onEditSubmit = (data: z.infer<typeof editTaskSchema>) => {
481	    updateTask.mutate(
482	      { showId, taskId: task.id, data },
483	      {
484	        onSuccess: () => {
485	          toast({ title: "Task updated" });
486	          setEditOpen(false);
487	          queryClient.invalidateQueries({ queryKey: getListTasksQueryKey(showId) });
488	          queryClient.invalidateQueries({ queryKey: getGetShowQueryKey(showId) });
489	        },
490	        onError: () => toast({ title: "Error updating task", variant: "destructive" }),
491	      }
492	    );
493	  };
494	
495	  return (
496	    <div className={`group flex flex-col p-3 rounded-lg border bg-card transition-all duration-300 ${justCompleted ? 'border-green-500/60 bg-green-500/8 scale-[1.01]' : task.completed ? 'opacity-60' : 'hover:border-primary/30'}`}>
497	      <div className="flex items-start gap-3">
498	        <div className={`mt-1 transition-transform duration-150 ${justCompleted ? 'scale-125' : 'scale-100'}`}>
499	          <Checkbox
500	            checked={task.completed}
501	            onCheckedChange={handleToggle}
502	            className={`transition-colors duration-300 ${task.completed ? 'data-[state=checked]:bg-green-500 data-[state=checked]:text-white border-green-500' : ''}`}
503	          />
504	        </div>
505	
506	        <div className="flex-1 min-w-0">
507	          <div className="flex flex-wrap items-center gap-2">
508	            {isKeyTask(task) && (
509	              <Star className="h-3.5 w-3.5 fill-amber-400 text-amber-400 shrink-0" />
510	            )}
511	            <span className={`relative font-medium transition-colors duration-500 ${task.completed ? 'text-muted-foreground' : ''}`}>
512	              {task.name}
513	              <span
514	                className={`absolute inset-y-0 left-0 flex items-center pointer-events-none ${justCompleted ? 'animate-strikethrough' : ''}`}
515	                aria-hidden="true"
516	                style={{ width: justCompleted ? undefined : task.completed ? '100%' : '0%' }}
517	              >
518	                <span className="block w-full h-px bg-current opacity-60" />
519	              </span>
520	            </span>
521	            {task.category && (
522	              <Badge variant="outline" className={`${getCategoryColor(task.category)} border-transparent text-xs py-0 h-5`}>
523	                {task.category}
524	              </Badge>
525	            )}
526	            {task.notes && !expanded && (
527	              <Button variant="ghost" size="icon" className="h-5 w-5 text-muted-foreground" onClick={() => setExpanded(true)}>
528	                <MessageSquare className="h-3 w-3" />
529	              </Button>
530	            )}
531	          </div>
532	
533	          <div className="flex flex-wrap items-center gap-3 mt-1.5 text-xs">
534	            {task.completed && task.completedAt ? (
535	              <Popover open={datePickerOpen} onOpenChange={setDatePickerOpen}>
536	                <PopoverTrigger asChild>
537	                  <button className="flex items-center gap-1 font-medium text-green-500 hover:text-green-400 hover:underline cursor-pointer">
538	                    <CheckCircle2 className="h-3 w-3" />
539	                    Done {format(new Date(task.completedAt), "MMM d, yyyy")}
540	                  </button>
541	                </PopoverTrigger>
542	                <PopoverContent className="w-auto p-3" align="start">
543	                  <p className="text-xs text-muted-foreground mb-2">Adjust completion date</p>
544	                  <input
545	                    type="date"
546	                    defaultValue={format(new Date(task.completedAt), "yyyy-MM-dd")}
547	                    className="flex h-9 w-full rounded-md border border-input bg-transparent px-3 py-1 text-sm shadow-sm"
548	                    onChange={(e) => onUpdateCompletedAt(e.target.value)}
549	                  />
550	                </PopoverContent>
551	              </Popover>
552	            ) : task.dueDate ? (
553	              <div className={`flex items-center gap-1 font-medium ${urgency.textClass}`}>
554	                <CalendarIcon className="h-3 w-3" />
555	                {formatDate(task.dueDate)}
556	                {urgency.daysRemaining !== null && (
557	                  <span className="ml-1 opacity-80">
558	                    ({Math.abs(urgency.daysRemaining)}d {urgency.daysRemaining < 0 ? 'ago' : 'left'})
559	                  </span>
560	                )}
561	              </div>
562	            ) : (
563	              <span className="text-muted-foreground">No due date</span>
564	            )}
565	            {task.dueDateRule && (
566	              <span className="text-muted-foreground italic border-l pl-3">
567	                {task.dueDateRule}
568	              </span>
569	            )}
570	          </div>
