import { Router } from "express";
import { db, showsTable, tasksTable, eblastsTable, linksTable, gcalOrphansTable } from "@workspace/db";
import { eq, and } from "drizzle-orm";
import {
  CreateShowBody,
  UpdateShowBody,
  GetShowParams,
  UpdateShowParams,
  DeleteShowParams,
} from "@workspace/api-zod";

const router = Router();

const DATE_FIELDS = [
  "moveInDate",
  "advanceWarehouseDate",
  "discountDeadline",
  "onlineOrderDeadline",
  "showStart",
  "dismantleDate",
] as const;

function sanitizeDates(body: Record<string, unknown>): Record<string, unknown> {
  const sanitized = { ...body };
  for (const field of DATE_FIELDS) {
    if (sanitized[field] === "" || sanitized[field] === undefined) {
      sanitized[field] = null;
    }
  }
  return sanitized;
}

function toDateStr(d: Date | null | undefined): string | null {
  if (!d) return null;
  return d.toISOString().split("T")[0];
}

