  show: typeof showsTable.$inferSelect,
  tasks: (typeof tasksTable.$inferSelect)[],
  eblasts: (typeof eblastsTable.$inferSelect)[]
) {
  const today = new Date();
  today.setHours(0, 0, 0, 0);
  const todayStr = today.toISOString().split("T")[0];
